function playPad(i,when=null,velocity=100){const p=state.pads[i],f=getFile(p.fileId);if(!f)return;if(when===null)stopPad(i);const ctx=audio(),source=ctx.createBufferSource(),gain=ctx.createGain(),begin=Math.max(0,p.start||0),end=Math.min(f.buffer.duration,p.end??f.buffer.duration);if(end-begin<.005)return;source.buffer=p.reverse?reversedBuffer(f.buffer):f.buffer;source.playbackRate.value=padRate(p);source.loop=p.loop;source.loopStart=p.reverse?f.buffer.duration-end:begin;source.loopEnd=p.reverse?f.buffer.duration-begin:end;const duration=(end-begin)/padRate(p);padEnvelope(gain,p,when??ctx.currentTime,duration,p.volume*Math.max(0,Math.min(1,velocity/100)));source.connect(gain).connect(state.master);const v={src:source,gain};state.voices.set(i,[...(state.voices.get(i)||[]),v]);document.querySelector(`.pad[data-pad="${i}"]`)?.classList.add('playing');source.onended=()=>{const vs=state.voices.get(i);if(vs?.includes(v)){state.voices.set(i,[]);if(!state.voices.get(i).length){state.voices.delete(i);document.querySelector(`.pad[data-pad="${i}"]`)?.classList.remove('playing')}}};source.start(when??0,p.reverse?f.buffer.duration-end:begin,p.loop?undefined:duration);}
