document.querySelectorAll('nav button[data-tab]').forEach(button=>{button.addEventListener('click',()=>showTab(button.dataset.tab));});
function showTab(tab){document.querySelectorAll('nav button[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===tab));$('heading').textContent=({record:'Record. Capture. Play.',sample:'Make sound playable.',edit:'Shape the waveform.',sequence:'Build patterns. Shape rhythm.',arrange:'Arrange. Compose. Build.',perform:'Play. Record. Improvise.'})[tab];if(tab==='edit')requestAnimationFrame(drawWave);if(tab==='sequence')renderSequencer();if(tab==='arrange')renderArrange();if(tab==='perform')renderPerfEvents()}
