wave.addEventListener('pointerdown',e=>{if(e.button!==0)return;const f=getFile(state.editId);if(!f)return;const r=wave.getBoundingClientRect(),v=viewBounds(f),t=v.start+(e.clientX-r.left)/r.width*v.span;drag={id:e.pointerId,select:e.shiftKey,x:e.clientX,origin:state.playback?.fid===f.id?playbackPosition():state.cursor,clickTime:Math.max(0,Math.min(f.buffer.duration,t)),moved:false,wasPlaying:Boolean(state.preview&&state.playback?.fid===f.id)};wave.setPointerCapture(e.pointerId);if(drag.select){state.sel=[drag.clickTime,drag.clickTime];drawWave();}else if(drag.wasPlaying){stopAll();state.cursor=drag.origin;}});
