function analysisUI(stage,pct,detail=''){$('analysisProgress').hidden=false;$('analysisStage').textContent=stage;$('analysisPercent').textContent=Math.round(pct)+'%';$('analysisBar').value=pct;if(detail)$('analysisDetail').textContent=detail;}
