$('cancelAnalysis').onclick=cancelAnalysis;
const analysisWorkerCode=`self.onmessage=e=>{try{const {samples,rate,start,duration,minBpm,maxBpm}=e.data;const n=samples.length;self.postMessage({type:'progress',pct:35,stage:'DETECTING TRANSIENTS'});const novelty=new Float32Array(n);for(let i=2;i<n;i++)novelty[i]=Math.max(0,samples[i]-samples[i-2]);const smooth=new Float32Array(n);for(let i=2;i<n-2;i++)smooth[i]=(novelty[i-2]+2*novelty[i-1]+3*novelty[i]+2*novelty[i+1]+novelty[i+2])/9;let avg=0;for(let i=0;i<n;i++)avg+=smooth[i];avg/=Math.max(1,n);const onsets=[];let last=-999;for(let i=2;i<n-2;i++){if(smooth[i]>Math.max(avg*1.6,0.00005)&&smooth[i]>=smooth[i-1]&&smooth[i]>smooth[i+1]&&i-last>rate*.085){onsets.push(start+i/rate);last=i;}}self.postMessage({type:'progress',pct:65,stage:'ESTIMATING TEMPO'});let bestBpm=null,best=-Infinity;const candidates=[];for(let step=Math.ceil(minBpm*10);step<=Math.floor(maxBpm*10);step++){const bpm=step/10,lag=rate*60/bpm,whole=Math.floor(lag),frac=lag-whole;let score=0;for(let i=whole+1;i<n;i++)score+=smooth[i]*(smooth[i-whole]*(1-frac)+smooth[i-whole-1]*frac);score/=Math.max(1,n-whole);candidates.push({bpm,score});if(score>best){best=score;bestBpm=bpm;}if(step%200===0)self.postMessage({type:'progress',pct:65+Math.round((bpm-minBpm)/(maxBpm-minBpm)*30),stage:'ESTIMATING TEMPO'});}if(duration<2||onsets.length<3||best<1e-10)bestBpm=null;candidates.sort((a,b)=>b.score-a.score);const alternatives=[];for(const c of candidates){if(alternatives.every(a=>Math.abs(a.bpm-c.bpm)>3))alternatives.push(c);if(alternatives.length>=5)break;}const confidence=best>0?Math.min(1,Math.max(0,(best-(alternatives[1]?.score||0))/best)):0;self.postMessage({type:'done',bpm:bestBpm,onsets,confidence,alternatives:alternatives.map(x=>x.bpm)});}catch(err){self.postMessage({type:'error',message:String(err.message||err)})}}`;
async function analyzeCurrent(){const f=getFile(state.editId);if(!f){msg('SELECT AUDIO FIRST');return null;}const cached=state.analysis.get(f.id);if(cached)return cached;if(activeAnalysis){if(activeAnalysis.fid===f.id)return activeAnalysis.promise;cancelAnalysis();}const started=performance.now();$('analyzeBpm').disabled=true;$('cancelAnalysis').hidden=false;$('bpmResult').textContent='BPM: ANALYZING…';analysisUI('PREPARING',0,'Preparing a representative segment (up to 90 seconds).');msg('BPM ANALYSIS STARTED');await new Promise(r=>setTimeout(r,30));if(!getFile(f.id))return null;
// Downsample to a compact amplitude envelope before transferring to the worker.
const rate=200, duration=Math.min(90,f.buffer.duration), start=f.buffer.duration>100?Math.min(10,f.buffer.duration-duration):0, count=Math.ceil(duration*rate), samples=new Float32Array(count),data=f.buffer.getChannelData(0),sr=f.buffer.sampleRate;let worker;
try{const blob=new Blob([analysisWorkerCode],{type:'application/javascript'});const url=URL.createObjectURL(blob);worker=new Worker(url);URL.revokeObjectURL(url);}catch(e){$('analyzeBpm').disabled=false;$('cancelAnalysis').hidden=true;analysisUI('ERROR',0,'Worker could not start: '+e.message);$('bpmResult').textContent='BPM: ERROR';msg('ANALYSIS FAILED');return null;}
let finish;const promise=new Promise(resolve=>{finish=resolve});const timer=setInterval(()=>{$('analysisElapsed').textContent=((performance.now()-started)/1000).toFixed(1)+'s'},100);activeAnalysis={fid:f.id,worker,timer,resolve:finish,promise};
worker.onmessage=e=>{if(activeAnalysis?.worker!==worker)return;const d=e.data;if(d.type==='progress'){analysisUI(d.stage,d.pct);return;}clearInterval(timer);worker.terminate();activeAnalysis=null;$('analyzeBpm').disabled=false;$('cancelAnalysis').hidden=true;if(d.type==='error'){analysisUI('ERROR',0,d.message);$('bpmResult').textContent='BPM: ERROR';msg('ANALYSIS FAILED · '+d.message);finish(null);return;}const result={bpm:d.bpm,onsets:d.onsets,confidence:d.confidence,alternatives:d.alternatives,offset:0};state.gridOffset=0;state.analysis.set(f.id,result);$('confidence').textContent=`CONFIDENCE ${Math.round((d.confidence||0)*100)}% · ALTERNATIVES ${(d.alternatives||[]).join(' / ')}`;analysisUI(d.bpm?'COMPLETE':'UNCERTAIN',100,d.bpm?'Estimated tempo only; check grid alignment. Try ÷2 if tempo appears doubled.':'No reliable tempo found; try TAP BPM.');$('bpmResult').textContent=d.bpm?`BPM: ${d.bpm.toFixed(1)} (EST.) · ${d.onsets.length} ONSETS`:`BPM: UNCERTAIN · ${d.onsets.length} ONSETS`;if(d.bpm)$('bpm').value=d.bpm.toFixed(1);drawWave();msg(d.bpm?`BPM ESTIMATE ${d.bpm.toFixed(1)} · VERIFY MANUALLY`:'BPM UNCERTAIN · ENTER BPM MANUALLY');finish(result);};worker.onerror=e=>{if(activeAnalysis?.worker!==worker)return;clearInterval(timer);worker.terminate();activeAnalysis=null;$('analyzeBpm').disabled=false;$('cancelAnalysis').hidden=true;analysisUI('ERROR',0,e.message||'Worker failed');$('bpmResult').textContent='BPM: ERROR';msg('BPM ANALYSIS FAILED');finish(null)};
// Chunk envelope preparation to allow status updates and cancellation.
const chunk=1500;for(let offset=0;offset<count;offset+=chunk){if(activeAnalysis?.worker!==worker)return promise;const end=Math.min(count,offset+chunk);for(let i=offset;i<end;i++){const a=Math.floor((start+i/rate)*sr),b=Math.min(data.length,Math.floor((start+(i+1)/rate)*sr));let sum=0;for(let j=a;j<b;j+=8){const x=data[j];sum+=x*x;}samples[i]=Math.sqrt(sum/Math.max(1,Math.ceil((b-a)/8)));}analysisUI('PREPARING',Math.round(end/count*30));await new Promise(r=>setTimeout(r,0));}if(activeAnalysis?.worker===worker)worker.postMessage({samples,rate,start,duration,minBpm:Number($('bpmRange').value.split(',')[0]),maxBpm:Number($('bpmRange').value.split(',')[1])},[samples.buffer]);return promise;}
function computeSlices(){const f=getFile(state.editId);if(!f){msg('SELECT AUDIO FIRST');return}const mode=$('sliceMode').value,n=Math.max(2,Math.min(16,Math.round(Number($('sliceCount').value)||8))),duration=f.buffer.duration;let boundaries=[0];if(mode==='equal'){for(let i=1;i<n;i++)boundaries.push(duration*i/n)}else if(mode==='beat'){const bpm=Number($('bpm').value)||120,beat=60/bpm;const beats=Math.max(1,Math.ceil(duration/beat));for(let i=1;i<n;i++)boundaries.push(Math.min(duration,Math.round(i*beats/n)*beat))}else{const a=state.analysis.get(f.id);if(!a){msg('RUN ANALYZE BPM FIRST FOR TRANSIENT SLICING');$('sliceResult').textContent='ANALYSIS REQUIRED';return}const candidates=a.onsets.filter(t=>t>.03&&t<duration-.03);if(candidates.length>=n-1){const ranked=candidates.map(t=>({t,score:0}));const hop=512,sr=f.buffer.sampleRate,channel=f.buffer.getChannelData(0);for(const r of ranked){const at=Math.floor(r.t*sr);let sum=0;for(let j=at;j<Math.min(channel.length,at+hop*3);j+=8)sum+=Math.abs(channel[j]);r.score=sum}ranked.sort((a,b)=>b.score-a.score);boundaries.push(...ranked.slice(0,n-1).map(x=>x.t).sort((a,b)=>a-b))}else boundaries.push(...candidates)}boundaries=Array.from(new Set([...boundaries,duration].map(x=>Math.min(duration,Math.max(0,x))))).sort((a,b)=>a-b).filter((x,i,arr)=>i===0||x-arr[i-1]>.01);if(boundaries.length<2){msg('NO VALID SLICES');return}state.slices=boundaries;$('sliceResult').textContent=`${boundaries.length-1} SLICES READY` ;drawWave();msg(`SLICE PREVIEW · ${boundaries.length-1} REGIONS`)}
$('analyzeBpm').onclick=()=>{if(state.analysis.has(state.editId)){state.analysis.delete(state.editId)}analyzeCurrent()};
