let chops=[];
function chopRender(){const box=$('chopList');box.replaceChildren();$('chopStatus').textContent=chops.length?`${chops.length} CHOPS · EDITABLE`:'NO CHOPS';for(let i=0;i<chops.length;i++){const c=chops[i],row=document.createElement('div');row.className='chop-row';const name=document.createElement('span');name.className='chop-name';name.textContent=`CHOP ${String(i+1).padStart(2,'0')}`;row.append(name);for(const edge of ['start','end']){const label=document.createElement('label');label.textContent=edge.toUpperCase();const field=document.createElement('input');field.type='number';field.min='0';field.max=getFile(state.editId)?.buffer.duration||0;field.step='0.001';field.value=c[edge].toFixed(3);field.addEventListener('change',()=>{const f=getFile(state.editId);if(!f)return;const val=Math.max(0,Math.min(f.buffer.duration,Number(field.value)));if(!Number.isFinite(val))return;const min=.015;if(edge==='start'){c.start=Math.min(val,c.end-min);if(i>0)chops[i-1].end=c.start;}else{c.end=Math.max(val,c.start+min);if(i<chops.length-1)chops[i+1].start=c.end;}chopRender();drawWave()});label.append(field);row.append(label)}const preview=document.createElement('button');preview.type='button';preview.textContent='▶ PREVIEW';preview.onclick=()=>{const f=getFile(state.editId);if(f)playFile(f,c.start,c.end)};row.append(preview);box.append(row)}}
function chopDetect(){const f=getFile(state.editId);if(!f){msg('SELECT AUDIO FIRST');return}const count=Math.max(2,Math.min(16,Math.round(Number($('chopCount').value)||8)));const sensitivity=Number($('chopSensitivity').value)/100;const mode=$('chopMode').value;let [from,to]=state.sel;from=Math.max(0,from||0);to=Math.min(f.buffer.duration,to||f.buffer.duration);if(to-from<.05){from=0;to=f.buffer.duration}if(to-from<.05){msg('AUDIO TOO SHORT');return}const sr=f.buffer.sampleRate;const channels=Array.from({length:f.buffer.numberOfChannels},(_,i)=>f.buffer.getChannelData(i));const hop=Math.max(128,Math.round(sr*.008));const frames=[];for(let pos=Math.floor(from*sr);pos<Math.floor(to*sr);pos+=hop){let sum=0,n=0;for(let k=pos;k<Math.min(channels[0].length,pos+hop);k+=Math.max(1,Math.floor(hop/64))){for(const ch of channels){sum+=ch[k]*ch[k];n++}}frames.push(Math.sqrt(sum/Math.max(1,n)))}const smooth=frames.map((_,i)=>{let v=0,n=0;for(let j=Math.max(0,i-2);j<=Math.min(frames.length-1,i+2);j++){v+=frames[j];n++}return v/n});const max=smooth.reduce((m,v)=>Math.max(m,v),1e-9),mean=smooth.reduce((a,b)=>a+b,0)/Math.max(1,smooth.length);let candidates=[];if(mode==='onset'){const lag=4;for(let i=lag+2;i<smooth.length-2;i++){const diff=smooth[i]-smooth[i-lag];if(diff>Math.max(mean*.12,max*(.015+(1-sensitivity)*.13))&&smooth[i]>=smooth[i-1]&&smooth[i]>=smooth[i+1])candidates.push({t:from+i*hop/sr,score:diff})}}else if(mode==='silence'){const threshold=Math.max(max*.007,mean*(.08+(1-sensitivity)*.65));let low=false,begin=0;for(let i=0;i<smooth.length;i++){if(smooth[i]<threshold){if(!low){low=true;begin=i}}else if(low){const end=i;if(end-begin>=Math.max(2,Math.round((.035+(1-sensitivity)*.09)*sr/hop))&&begin>2&&end<smooth.length-2)candidates.push({t:from+(begin+end)*.5*hop/sr,score:(end-begin)*hop/sr});low=false}}}let boundaries=[from,to];if(mode==='equal'){for(let i=1;i<count;i++)boundaries.push(from+(to-from)*i/count)}else{const minGap=Math.max(.045,(to-from)/(count*5));candidates.sort((a,b)=>b.score-a.score);for(const c of candidates){if(boundaries.length>=count+1)break;if(boundaries.every(t=>Math.abs(t-c.t)>minGap))boundaries.push(c.t)}if(boundaries.length<count+1){for(let i=1;i<count;i++){const t=from+(to-from)*i/count;if(boundaries.length>=count+1)break;if(boundaries.every(b=>Math.abs(b-t)>minGap))boundaries.push(t)}}}boundaries.sort((a,b)=>a-b);chops=[];for(let i=0;i<boundaries.length-1;i++){if(boundaries[i+1]-boundaries[i]>=.015)chops.push({start:boundaries[i],end:boundaries[i+1]})}chopRender();drawWave();msg(`${chops.length} CHOPS DETECTED · REVIEW BOUNDARIES`)}
$('chopSensitivity').oninput=()=>{$('chopSensitivityVal').textContent=$('chopSensitivity').value+'%'};
$('chopAnalyze').onclick=chopDetect;
$('chopAssign').onclick=()=>{const f=getFile(state.editId);if(!f||!chops.length){msg('DETECT CHOPS FIRST');return}const first=Number($('chopStartPad').value)||0;const n=Math.min(chops.length,16-first);if(n<=0)return;const occupied=Array.from({length:n},(_,i)=>first+i).filter(i=>state.pads[i].fileId);if(occupied.length&&!confirm(`Replace ${occupied.length} occupied PAD(s)? Original audio remains unchanged.`))return;for(let i=0;i<n;i++){const p=state.pads[first+i];stopPad(first+i);Object.assign(p,{fileId:f.id,start:chops[i].start,end:chops[i].end,originHotCue:null,originFileId:null,loop:false})}selectPad(first);showTab('sample');msg(`${n} CHOPS ASSIGNED · SOURCE PRESERVED`)};
