$('beatGrid').onchange=e=>{state.grid=e.target.checked;drawWave()};$('showTransients').onchange=e=>{state.transientsVisible=e.target.checked;drawWave()};$('bpm').addEventListener('input',()=>drawWave());$('detectSlices').onclick=computeSlices;$('assignSlices').onclick=()=>{const f=getFile(state.editId);if(!f)return;if(state.slices.length<2)computeSlices();if(state.slices.length<2)return;const n=Math.min(16,state.slices.length-1);for(let i=0;i<n;i++){stopPad(i);Object.assign(state.pads[i],{fileId:f.id,start:state.slices[i],end:state.slices[i+1],loop:false})}selectPad(0);showTab('sample');msg(`${n} SLICES ASSIGNED TO PADS`)};
$('tap').onclick=()=>{const t=performance.now();state.taps=state.taps.filter(x=>t-x<3000);state.taps.push(t);if(state.taps.length>1){let ds=state.taps.slice(1).map((x,i)=>x-state.taps[i]),bpm=Math.round(60000/(ds.reduce((a,b)=>a+b,0)/ds.length));$('bpm').value=Math.max(30,Math.min(300,bpm))}};

// ARRANGE: non-destructive regions in beat units, using shared AudioContext.
const arr={tracks:[{id:'t1',name:'AUDIO 1',volume:0.85,mute:false,solo:false},{id:'t2',name:'AUDIO 2',volume:0.85,mute:false,solo:false},{id:'t3',name:'AUDIO 3',volume:0.85,mute:false,solo:false}],regions:[],selected:null,position:0,running:false,started:0,startBeat:0,sources:[],frame:0,zoom:80,drag:null};
const arrBpm=()=>Math.max(30,Math.min(300,Number($('bpm').value)||120));
const beatSec=()=>60/arrBpm();
const arrSnap=b=>Math.max(0,$('arrSnap').checked?Math.round(b):b);
const arrBeats=()=>Math.max(64,...arr.regions.map(r=>r.at+r.length+8));
function sequenceRegionSnapshot(){const seq=state.seq;return {kind:'sequence',steps:seq.steps.map(row=>row.slice(0,seq.length).map(Boolean)),pads:state.pads.map(p=>({...p})),stepCount:seq.length,swing:Number(seq.swing)||0,velocity:seq.velocity.map(row=>row.slice(0,seq.length)),timing:seq.timing.map(row=>row.slice(0,seq.length))};}
function arrScheduleSequence(r,tr,from,now,ctx){
 const stepCount=r.stepCount===32?32:16, stepBeats=.25, cycle=stepCount*stepBeats;
 const first=Math.max(from,r.at),last=r.at+r.length,soloGain=Math.max(0,Number(tr.volume)||0);
 // Each hit is positioned in beat units. Swing delays odd sixteenths without changing the bar length.
 const firstCycle=Math.max(0,Math.floor((first-r.at)/cycle));
 for(let c=firstCycle;r.at+c*cycle<last;c++){
  for(let step=0;step<stepCount;step++){
   const baseBeat=r.at+c*cycle+step*stepBeats+(step%2===1?stepBeats*(Number(r.swing)||0)/100:0);
   for(let padIndex=0;padIndex<16;padIndex++){
    const hitBeat=baseBeat+Math.max(-60,Math.min(60,Number(r.timing?.[padIndex]?.[step])||0))/1000/beatSec();
    if(hitBeat<first-1e-7||hitBeat>=last-1e-7)continue;
    const when=now+(hitBeat-from)*beatSec();
    if(!r.steps?.[padIndex]?.[step])continue;
    const pad=r.pads?.[padIndex],file=getFile(pad?.fileId);
    if(!file)continue;
    const begin=Math.max(0,Number(pad.start)||0),end=Math.min(file.buffer.duration,pad.end==null?file.buffer.duration:Number(pad.end));
    const speed=Math.max(.01,Number(pad.speed)||1);if(end-begin<=.005)continue;
    const source=ctx.createBufferSource(),gain=ctx.createGain();source.buffer=pad.reverse?reversedBuffer(file.buffer):file.buffer;
    source.playbackRate.value=padRate(pad);source.loop=Boolean(pad.loop);source.loopStart=pad.reverse?file.buffer.duration-end:begin;source.loopEnd=pad.reverse?file.buffer.duration-begin:end;
    padEnvelope(gain,pad,when,(end-begin)/padRate(pad),(Number(pad.volume)??1)*soloGain*Math.max(0,Math.min(1,(Number(r.velocity?.[padIndex]?.[step])??100)/100)));source.connect(gain).connect(state.master);
    const offset=pad.reverse?file.buffer.duration-end:begin;
    source.start(when,offset,pad.loop?undefined:(end-begin)/padRate(pad));
    if(pad.loop){const remaining=(last-hitBeat)*beatSec();source.stop(when+remaining);}
    arr.sources.push({src:source,gain});
   }
  }
 }
}

// v0.6.8: unquantized pad performance, stored as beat-relative event snapshots.
const perf={recording:false,started:0,bpm:120,events:[],pads:[],duration:0,preview:[],playing:false,stopTimer:null};
function perfBeatSec(){return 60/Math.max(30,Math.min(300,perf.bpm||120));}
function perfStatus(t){const e=$('perfStatus');if(e)e.textContent=t;}
function perfStopPreview(){for(const v of perf.preview){try{v.src.stop()}catch{}try{v.src.disconnect();v.gain.disconnect()}catch{}}perf.preview=[];perf.playing=false;clearTimeout(perf.stopTimer);$('perfPreview').textContent='▶ PREVIEW TAKE';}
function perfStart(){perfStopPreview();if(perf.recording)return;stopSequencer();stopArrange();perf.events=[];perf.pads=state.pads.map(p=>({...p}));perf.bpm=Math.max(30,Math.min(300,Number($('bpm').value)||120));perf.duration=0;perf.started=audio().currentTime;perf.recording=true;$('perfRecord').textContent='■ STOP RECORDING';perfStatus('● RECORDING · FREE TIMING · '+perf.bpm.toFixed(1)+' BPM');renderPerfEvents();}
function perfStop(){if(!perf.recording)return;perf.duration=Math.max(0,(audio().currentTime-perf.started)/perfBeatSec());perf.recording=false;$('perfRecord').textContent='● RECORD TAKE';perfStatus('TAKE READY · '+perf.events.length+' HITS · '+perf.duration.toFixed(2)+' BEATS');renderPerfEvents();}
function perfHit(i){if(perf.recording){const beat=Math.max(0,(audio().currentTime-perf.started)/perfBeatSec());perf.events.push({pad:i,beat});perf.duration=Math.max(perf.duration,beat+.25);renderPerfEvents();}playPad(i);}
function perfSource(p,when,trackGain=1,clipEnd=null){const f=getFile(p?.fileId);if(!f)return null;const ctx=audio(),begin=Math.max(0,Number(p.start)||0),end=Math.min(f.buffer.duration,p.end==null?f.buffer.duration:Number(p.end)),speed=Math.max(.01,Number(p.speed)||1);if(end-begin<.005)return null;const source=ctx.createBufferSource(),gain=ctx.createGain();source.buffer=p.reverse?reversedBuffer(f.buffer):f.buffer;source.playbackRate.value=padRate(p);source.loop=Boolean(p.loop);source.loopStart=p.reverse?f.buffer.duration-end:begin;source.loopEnd=p.reverse?f.buffer.duration-begin:end;padEnvelope(gain,p,when,(end-begin)/padRate(p),(Number(p.volume)??1)*trackGain);source.connect(gain).connect(state.master);source.start(Math.max(ctx.currentTime,when),p.reverse?f.buffer.duration-end:begin,p.loop?undefined:(end-begin)/padRate(p));if(p.loop&&clipEnd!=null)source.stop(clipEnd);return {src:source,gain};}
function renderPerfEvents(){const el=$('perfEvents');if(!el)return;el.textContent=perf.events.length?perf.events.map(e=>`PAD ${String(e.pad+1).padStart(2,'0')} @ ${e.beat.toFixed(2)} beats`).join('  ·  '):'No recorded hits yet.';}
function arrSchedulePerformance(r,tr,from,now,ctx){const end=r.at+r.length,vol=Math.max(0,Number(tr.volume)||0);for(const e of r.events||[]){const beat=r.at+e.beat;if(beat<from||beat>=end)continue;const when=now+(beat-from)*beatSec();const voice=perfSource(r.pads?.[e.pad],when,vol,now+(end-from)*beatSec());if(voice)arr.sources.push(voice);}}
