$('perfPreview').onclick=()=>{if(perf.playing){perfStopPreview();return;}if(perf.recording)perfStop();if(!perf.events.length){msg('RECORD A TAKE FIRST');return;}const ctx=audio(),now=ctx.currentTime+.08,scale=60/Math.max(30,Number($('bpm').value)||120);perf.playing=true;$('perfPreview').textContent='■ STOP PREVIEW';for(const e of perf.events){const voice=perfSource(perf.pads[e.pad],now+e.beat*scale,1,now+Math.max(perf.duration,e.beat+.25)*scale);if(voice)perf.preview.push(voice);}perf.stopTimer=setTimeout(perfStopPreview,(Math.max(perf.duration,1)*scale+1)*1000);};
