const perfPadBox=$('perfPads');for(let i=0;i<16;i++){const b=document.createElement('button');b.className='perf-pad';b.textContent='PAD '+String(i+1).padStart(2,'0');b.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();perfHit(i)});perfPadBox.append(b);}renderPerfEvents();
