function arrWaveSVG(f){if(!f)return '';const data=f.buffer.getChannelData(0),samples=80,step=Math.max(1,Math.floor(data.length/samples));let path='';for(let i=0;i<samples;i++){let peak=0;for(let j=i*step;j<Math.min(data.length,(i+1)*step);j+=Math.max(1,Math.floor(step/48)))peak=Math.max(peak,Math.abs(data[j]));const x=i*100/(samples-1),h=Math.min(45,peak*42);path+=`M${x.toFixed(2)} ${(50-h).toFixed(2)}V${(50+h).toFixed(2)} `;}return `<svg preserveAspectRatio="none" viewBox="0 0 100 100" aria-hidden="true"><path d="${path}" stroke="currentColor" stroke-width=".6" fill="none"/></svg>`;}
