function renderArrangeInspector(){const box=$('arrInspector');if(!box)return;box.replaceChildren();const r=arr.regions.find(r=>r.id===arr.selected?.region),tr=arr.tracks.find(t=>t.id===(r?.track||arr.selected?.track));if(!tr){box.textContent='Select a region or track.';return;}const title=document.createElement('p');title.textContent=tr.name;box.append(title);if(r){const f=getFile(r.fileId);for(const [label,value] of [['SOURCE',r.kind==='sequence'?'PATTERN SNAPSHOT':r.kind==='performance'?'PAD PERFORMANCE TAKE':(f?.name||'Missing')],['START BEAT',r.at.toFixed(2)],['LENGTH',r.length.toFixed(2)],['DETAIL',r.kind==='sequence'?(r.stepCount+' steps · '+r.swing+'% swing'):r.kind==='performance'?(r.events.length+' hits · unquantized'):(r.offset.toFixed(2)+'s')]]){const p=document.createElement('p');p.textContent=label+' · '+value;box.append(p)}const del=document.createElement('button');del.textContent='DELETE REGION';del.onclick=()=>{arr.regions=arr.regions.filter(x=>x.id!==r.id);arr.selected=null;renderArrange()};box.append(del);const dup=document.createElement('button');dup.textContent='DUPLICATE';dup.onclick=()=>{arr.regions.push({...r,id:id(),at:r.at+r.length});renderArrange()};box.append(dup)}}
