function renderSequencer(){const s=state.seq,grid=$('seqGrid');if(!grid)return;grid.style.setProperty('--steps',s.length);grid.replaceChildren();for(let i=0;i<16;i++){const label=document.createElement('button');label.className='seq-track';label.textContent=`${String(i+1).padStart(2,'0')} · ${(getFile(state.pads[i].fileId)?.name||'EMPTY').slice(0,18)}`;label.title='Preview pad '+(i+1);label.onclick=()=>playPad(i);grid.append(label);for(let k=0;k<s.length;k++){const b=document.createElement('button');b.className='seq-cell'+(s.steps[i][k]?' on':'')+(k%4===0?' beat':'')+(s.highlight===k?' current':'');b.setAttribute('aria-label',`Pad ${i+1}, step ${k+1}`);b.setAttribute('aria-pressed',String(s.steps[i][k]));b.title=`PAD ${i+1} / STEP ${k+1} · VELOCITY ${s.velocity[i][k]}% · TIMING ${s.timing[i][k]}ms`;b.classList.toggle("selected-step",s.selectedCell?.pad===i&&s.selectedCell?.step===k);b.onclick=()=>{s.selectedCell={pad:i,step:k};renderStepControls();grid.querySelectorAll(".selected-step").forEach(x=>x.classList.remove("selected-step"));b.classList.add("selected-step");s.steps[i][k]=!s.steps[i][k];b.classList.toggle('on',s.steps[i][k]);b.setAttribute('aria-pressed',String(s.steps[i][k]));};grid.append(b);}}}
