// Portable project: binary container with UTF-8 manifest and untouched original audio blobs.
// Format: 8 ASCII magic bytes, 4-byte big-endian manifest length, JSON manifest, concatenated source audio bytes.
const PROJECT_MAGIC='FSPROJ01';
function projectSnapshot(){return {files:state.files.map(({id,name,blob})=>({id,name,blob})),pads:state.pads,bpm:$('bpm').value,master:$('master').value,sequence:{steps:state.seq.steps,length:state.seq.length,swing:state.seq.swing,velocity:state.seq.velocity,timing:state.seq.timing},cues:Object.fromEntries(cueData),eq:Object.fromEntries(eqSettings),noise:Object.fromEntries(noiseSettings),arrangement:{tracks:arr.tracks,regions:arr.regions,position:arr.position}};}
